sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float progress;
uniform float grain;
uniform float seed;
float hash(float2 p) { p = fract(p * float2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
half4 main(float2 coord) {
    return image.eval(coord) * half(step(progress, hash(floor(coord / max(grain, 1)) + seed * float2(17.13, 41.71))));
}
